// SDMMC_ADMA_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module SDMMC_ADMA_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [9:0] c_clk_div,
  input logic  c_clk_en,
  input logic [1:0] c_bus_w,
  input logic [11:0] c_blksz,
  input logic [15:0] c_blkcnt,
  input logic [23:0] c_dto,
  input logic [31:0] c_adma_addr,
  input logic [31:0] c_c_arg,
  input logic [5:0] c_c_idx,
  input logic [1:0] c_c_rsp,
  input logic  c_c_crc_chk,
  input logic  c_c_idx_chk,
  input logic [1:0] c_c_data,
  input logic  c_c_start,
  input logic  c_dat_reset,
  input logic [31:0] c_rsp0,
  input logic [31:0] c_rsp1,
  input logic [31:0] c_rsp2,
  input logic [31:0] c_rsp3,
  input logic  c_cmd_busy,
  input logic  c_dat_busy,
  input logic [4:0] c_c_err,
  input logic [7:0] c_d_err,
  input logic [15:0] c_blk_done,
  input logic [31:0] c_adma_cur,
  input logic  c_cmd_done,
  input logic  c_cmd_err,
  input logic  c_xfer_done,
  input logic  c_xfer_err,
  input logic  c_dma_int
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 19;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:18];          // model of every stored word
  logic [4:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;

  always_comb begin
    m_set = '0;
    if (c_cmd_done) m_set[0] = 1'b1;
    if (c_cmd_err) m_set[1] = 1'b1;
    if (c_xfer_done) m_set[2] = 1'b1;
    if (c_xfer_err) m_set[3] = 1'b1;
    if (c_dma_int) m_set[4] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'hF9;
      m_w[6] <= 32'h1200;
      m_w[7] <= 32'hFFFFFF;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h300;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_w[18] <= 32'h0;
      m_pulse_CMD <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h1F;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h1FFF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 10) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'hFFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 11) ? PWDATA & m_be & 32'h3 : 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h5C610100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 0;
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return 0;
      12: return (32'(c_rsp0) << 0);
      13: return (32'(c_rsp1) << 0);
      14: return (32'(c_rsp2) << 0);
      15: return (32'(c_rsp3) << 0);
      16: return (32'(c_cmd_busy) << 0) | (32'(c_dat_busy) << 1) | (32'(c_c_err) << 2) | (32'(c_d_err) << 7);
      17: return (32'(c_blk_done) << 0);
      18: return (32'(c_adma_cur) << 0);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][4:0] & m_w[2][4:0]))
  `SVA_INV(a_core_clk_div, c_clk_div == m_w[5][9:0])
  `SVA_INV(a_core_clk_en, c_clk_en == m_w[5][10:10])
  `SVA_INV(a_core_bus_w, c_bus_w == m_w[5][12:11])
  `SVA_INV(a_core_blksz, c_blksz == m_w[6][11:0])
  `SVA_INV(a_core_blkcnt, c_blkcnt == m_w[6][27:12])
  `SVA_INV(a_core_dto, c_dto == m_w[7][23:0])
  `SVA_INV(a_core_adma_addr, c_adma_addr == m_w[8][31:0])
  `SVA_INV(a_core_c_arg, c_c_arg == m_w[9][31:0])
  `SVA_INV(a_core_c_idx, c_c_idx == m_w[10][5:0])
  `SVA_INV(a_core_c_rsp, c_c_rsp == m_w[10][7:6])
  `SVA_INV(a_core_c_crc_chk, c_c_crc_chk == m_w[10][8:8])
  `SVA_INV(a_core_c_idx_chk, c_c_idx_chk == m_w[10][9:9])
  `SVA_INV(a_core_c_data, c_c_data == m_w[10][11:10])
  `SVA_INV(a_core_c_start, c_c_start == m_pulse_CMD[0])
  `SVA_INV(a_core_dat_reset, c_dat_reset == m_pulse_CMD[1])
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_clk_div == 10'hF9 && c_clk_en == 1'h0 && c_bus_w == 2'h0 && c_blksz == 12'h200 && c_blkcnt == 16'h1 && c_dto == 24'hFFFFFF && c_adma_addr == 32'h0 && c_c_arg == 32'h0 && c_c_idx == 6'h0 && c_c_rsp == 2'h0 && c_c_crc_chk == 1'h1 && c_c_idx_chk == 1'h1 && c_c_data == 2'h0 && c_c_start == 1'h0 && c_dat_reset == 1'h0)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CFG, m_rd && m_map && m_idx == 5)
  `FC(wr_CFG, m_wr && m_map && m_idx == 5)
  `FC(rd_BLK, m_rd && m_map && m_idx == 6)
  `FC(wr_BLK, m_wr && m_map && m_idx == 6)
  `FC(rd_DTO, m_rd && m_map && m_idx == 7)
  `FC(wr_DTO, m_wr && m_map && m_idx == 7)
  `FC(rd_ADMA_ADDR, m_rd && m_map && m_idx == 8)
  `FC(wr_ADMA_ADDR, m_wr && m_map && m_idx == 8)
  `FC(rd_CMD_ARG, m_rd && m_map && m_idx == 9)
  `FC(wr_CMD_ARG, m_wr && m_map && m_idx == 9)
  `FC(rd_CMD_CTRL, m_rd && m_map && m_idx == 10)
  `FC(wr_CMD_CTRL, m_wr && m_map && m_idx == 10)
  `FC(rd_CMD, m_rd && m_map && m_idx == 11)
  `FC(wr_CMD, m_wr && m_map && m_idx == 11)
  `FC(rd_RSP0, m_rd && m_map && m_idx == 12)
  `FC(wr_RSP0, m_wr && m_map && m_idx == 12)
  `FC(rd_RSP1, m_rd && m_map && m_idx == 13)
  `FC(wr_RSP1, m_wr && m_map && m_idx == 13)
  `FC(rd_RSP2, m_rd && m_map && m_idx == 14)
  `FC(wr_RSP2, m_wr && m_map && m_idx == 14)
  `FC(rd_RSP3, m_rd && m_map && m_idx == 15)
  `FC(wr_RSP3, m_wr && m_map && m_idx == 15)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 16)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 16)
  `FC(rd_BLK_DONE, m_rd && m_map && m_idx == 17)
  `FC(wr_BLK_DONE, m_wr && m_map && m_idx == 17)
  `FC(rd_ADMA_CUR, m_rd && m_map && m_idx == 18)
  `FC(wr_ADMA_CUR, m_wr && m_map && m_idx == 18)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_CMD_DONE_set, m_set[0])
  `FC(irq_CMD_DONE_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_CMD_DONE_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_CMD_DONE_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_CMD_ERR_set, m_set[1])
  `FC(irq_CMD_ERR_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_CMD_ERR_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_CMD_ERR_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_XFER_DONE_set, m_set[2])
  `FC(irq_XFER_DONE_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_XFER_DONE_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_XFER_DONE_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_XFER_ERR_set, m_set[3])
  `FC(irq_XFER_ERR_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_XFER_ERR_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_XFER_ERR_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_DMA_INT_set, m_set[4])
  `FC(irq_DMA_INT_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_DMA_INT_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_DMA_INT_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(cmd_c_start, m_pulse_CMD[0])
  `FC(cmd_dat_reset, m_pulse_CMD[1])
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind SDMMC_ADMA_apb SDMMC_ADMA_apb_sva u_apb_sva (.*);
